import React, { useEffect, useState } from 'react';
import { Table, Button, Modal, Form, Input, InputNumber, message, Space, Popconfirm, Typography, Card, Tag, Switch } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, ShopOutlined, ReloadOutlined } from '@ant-design/icons';
import request from '@/utils/request';
import { formatTime } from '@/utils/format';

const { Title, Text } = Typography;

interface Shop {
  id: string;
  name: string;
  description: string;
  address: string;
  phone: string;
  logoUrl: string;
  status: string;
  deliveryRange: number;
  deliveryFee: number;
  minOrderAmount: number;
  createdAt: string;
  updatedAt: string;
}

const ShopManagePage: React.FC = () => {
  const [shops, setShops] = useState<Shop[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalVisible, setModalVisible] = useState(false);
  const [editingShop, setEditingShop] = useState<Shop | null>(null);
  const [form] = Form.useForm();

  useEffect(() => {
    loadShops();
  }, []);

  const loadShops = async () => {
    setLoading(true);
    try {
      const res = await request.get('/api/shops');
      setShops(res || []);
    } catch (error) {
      console.error('加载店铺失败:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = () => {
    setEditingShop(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (record: Shop) => {
    setEditingShop(record);
    form.setFieldsValue({
      ...record,
      deliveryRange: record.deliveryRange ? record.deliveryRange / 1000 : 3,
      deliveryFee: record.deliveryFee ? record.deliveryFee / 100 : 5,
      minOrderAmount: record.minOrderAmount ? record.minOrderAmount / 100 : 0,
    });
    setModalVisible(true);
  };

  const handleDelete = async (id: string) => {
    try {
      await request.delete(`/api/shops/${id}`);
      message.success('删除成功');
      loadShops();
    } catch (error) {
      message.error('删除失败');
    }
  };

  const handleStatusChange = async (record: Shop, checked: boolean) => {
    try {
      await request.patch(`/api/shops/${record.id}`, {
        status: checked ? 'open' : 'closed',
      });
      message.success('状态更新成功');
      loadShops();
    } catch (error) {
      message.error('状态更新失败');
    }
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      const data = {
        ...values,
        deliveryRange: values.deliveryRange * 1000,
        deliveryFee: values.deliveryFee * 100,
        minOrderAmount: values.minOrderAmount * 100,
      };

      if (editingShop) {
        await request.patch(`/api/shops/${editingShop.id}`, data);
        message.success('更新成功');
      } else {
        await request.post('/api/shops', data);
        message.success('创建成功');
